25	fn extract_a_values(line: &str) -> Option<Vec<String>> {
26	    let pos = line.find(" -a '")?;
27	    let rest = &line[pos + 5..];
28	    let end = rest.find('\'')?;
29	    Some(
30	        rest[..end]
31	            .split_whitespace()
32	            .map(|s| s.to_string())
33	            .collect(),
34	    )
