37	/// All `-a` tokens from `__fish_use_subcommand` lines — the proposed top-level commands.
38	fn completion_top_level(completions: &str) -> HashSet<String> {
39	    let mut out = HashSet::new();
40	    for line in completions.lines() {
41	        if line.contains("__fish_use_subcommand") {
42	            if let Some(vals) = extract_a_values(line) {
43	                out.extend(vals);
44	            }
45	        }
46	    }
47	    out
