50	/// Per-parent `-a` tokens from `__fish_seen_subcommand_from PARENT` lines,
51	/// excluding lines that define `--long` flag completions (`-l`).
52	fn completion_subcommands(completions: &str) -> HashMap<String, HashSet<String>> {
53	    let mut map: HashMap<String, HashSet<String>> = HashMap::new();
54	    for line in completions.lines() {
55	        if !line.contains("__fish_seen_subcommand_from ") {
56	            continue;
57	        }
58	        // Skip long-flag completions (they don't name subcommands)
59	        if line.contains(" -l ") {
60	            continue;
61	        }
62	        let Some(vals) = extract_a_values(line) else {
63	            continue;
64	        };
65	        let Some(from_pos) = line.find("__fish_seen_subcommand_from ") else {
66	            continue;
67	        };
68	        let after = &line[from_pos + "__fish_seen_subcommand_from ".len()..];
69	        let parent: String = after.trim_start_matches('\'').split('\'').next().unwrap_or("").into();
70	        if parent.is_empty() {
71	            continue;
72	        }
73	        map.entry(parent).or_default().extend(vals);
74	    }
75	    map
76	}
