85	        .expect("residual --help");
86	    let text = String::from_utf8(out.stdout).unwrap();
87	    let mut in_cmds = false;
88	    let mut result = HashSet::new();
89	    for line in text.lines() {
90	        if line.trim_end() == "Commands:" {
91	            in_cmds = true;
92	            continue;
93	        }
94	        if !in_cmds {
95	            continue;
96	        }
97	        if line.starts_with("Options:") || line.starts_with("Arguments:") {
98	            break;
99	        }
100	        let trimmed = line.trim();
101	        if trimmed.is_empty() {
102	            continue;
103	        }
104	        if let Some(name) = trimmed.split_whitespace().next() {
105	            if name != "help" {
106	                result.insert(name.to_string());
107	            }
108	        }
109	    }
110	    result
